def collect_agents(agent):
    agents.append(agent.name)
    if hasattr(agent, 'sub_agents') and agent.sub_agents:
        for sub_agent in agent.sub_agents:
            collect_agents(sub_agent)

collect_agents(self.root_agent)
return agents

