def __init__(
    self, base_url: str = "http://127.0.0.1:8000", timeout: float = 30.0
):
    self.base_url = base_url.rstrip("/")
    self.timeout = timeout
    self._client: Optional[httpx.AsyncClient] = None

async def _get_client(self) -> AsyncGenerator[httpx.AsyncClient, None]:
    if self._client is None:
        self._client = httpx.AsyncClient(
            base_url=self.base_url,
            timeout=httpx.Timeout(self.timeout),
        )
    try:
        yield self._client
    finally:
        pass

def success_rate(self) -> float:
    if self.total_tests == 0:
        return 0.0
    return (self.passed_tests / self.total_tests) * 100

def _print_test_case_result(result: _TestResult) -> None:

  if result.success:
    click.secho(" ✓ PASS", fg="green")
  else:
    click.secho(" ✗ FAIL", fg="red")
    if result.error_message:
      click.secho(f"Error: {result.error_message}", fg="red", err=True)

